import json

# Let's parse the JSON to find if there's more data
with open('/app/resources/treasury_bulletin_2003_03.json', 'r') as f:
    data = json.load(f)

# Navigate to find the market yields table
# Let's look at elements that contain 'MY-2' or yield data
def find_table(element):
    if isinstance(element, dict):
        content = element.get('content', '')
        if 'MY-2' in content or 'Average Yields' in content:
            return element
        for v in element.values():
            result = find_table(v)
            if result:
                return result
    elif isinstance(element, list):
        for item in element:
            result = find_table(item)
            if result:
                return result
    return None

# Search for table with MY-2
for elem in data.get('document', {}).get('elements', []):
    if isinstance(elem, dict):
        content = str(elem.get('content', ''))
        if 'MY-2' in content or ('Aa corporate' in content.lower() and 'bond' in content.lower()):
            print(f"Found: {content[:200]}")
            print(f"ID: {elem.get('id')}")
            print()
