python3 << 'EOF'
import json
import re

with open('/app/resources/treasury_bulletin_2003_03.json', 'r') as f:
    data = json.load(f)

# Search for elements with table data containing 2003
def search_2003(element, path=''):
    results = []
    if isinstance(element, dict):
        content = str(element.get('content', ''))
        if '2003' in content and ('6.' in content or '5.' in content or '7.' in content):
            # Check if this looks like yield data (has decimal numbers)
            if re.search(r'\d+\.\d+', content):
                results.append((path + str(element.get('id')), content[:300]))
        for k, v in element.items():
            results.extend(search_2003(v, path + k + '.'))
    elif isinstance(element, list):
        for i, item in enumerate(element):
            results.extend(search_2003(item, path + f'[{i}].'))
    return results

# Search all elements
all_results = []
for elem in data.get('document', {}).get('elements', []):
    all_results.extend(search_2003(elem))

# Print unique results
for path, content in all_results[:20]:
    print(f"Path: {path}")
    print(f"Content: {content}")
    print("---")
